#[test]
fn bcrypt_pbkdf_matches_the_reference_vectors() {
    let mut out = [0u8; 32];
    let mut scratch = [0u8; bcrypt_pbkdf_scratch_len(32)];
    bcrypt_pbkdf(&V0_PASSPHRASE, &V0_SALT, V0_ROUNDS, &mut out, &mut scratch)
        .expect("vector 0 derives");
    assert_eq!(out, V0_EXPECTED, "vector 0");

    let mut out = [0u8; 32];
    let mut scratch = [0u8; bcrypt_pbkdf_scratch_len(32)];
    bcrypt_pbkdf(&V1_PASSPHRASE, &V1_SALT, V1_ROUNDS, &mut out, &mut scratch)
        .expect("vector 1 derives");
    assert_eq!(out, V1_EXPECTED, "vector 1");

    let mut out = [0u8; 88];
    let mut scratch = [0u8; bcrypt_pbkdf_scratch_len(88)];
    bcrypt_pbkdf(&V2_PASSPHRASE, &V2_SALT, V2_ROUNDS, &mut out, &mut scratch)
        .expect("vector 2 derives");
    assert_eq!(out, V2_EXPECTED, "vector 2");
}

#[test]
fn bcrypt_pbkdf_refuses_malformed_inputs() {
    let mut out = [0u8; 32];
    let mut scratch = [0u8; 32];

    assert_eq!(
        bcrypt_pbkdf(&[], &V0_SALT, V0_ROUNDS, &mut out, &mut scratch),
        Err(BcryptPbkdfError(())),
        "an empty passphrase"
    );
    assert_eq!(
        bcrypt_pbkdf(&V0_PASSPHRASE, &[], V0_ROUNDS, &mut out, &mut scratch),
        Err(BcryptPbkdfError(())),
        "an empty salt"
    );
    assert_eq!(
        bcrypt_pbkdf(&V0_PASSPHRASE, &V0_SALT, 0, &mut out, &mut scratch),
        Err(BcryptPbkdfError(())),
        "zero rounds"
    );
    assert_eq!(
        bcrypt_pbkdf(&V0_PASSPHRASE, &V0_SALT, V0_ROUNDS, &mut [], &mut scratch),
        Err(BcryptPbkdfError(())),
        "an empty output"
    );

    // A scratch buffer one block short is refused rather than truncating
    // the derivation.
    let mut short = [0u8; 31];
    assert_eq!(
        bcrypt_pbkdf(&V0_PASSPHRASE, &V0_SALT, V0_ROUNDS, &mut out, &mut short),
        Err(BcryptPbkdfError(())),
        "a short scratch buffer"
    );
}

#[test]
fn the_scratch_rule_rounds_up_to_the_block() {
    assert_eq!(bcrypt_pbkdf_scratch_len(0), 0);
    assert_eq!(bcrypt_pbkdf_scratch_len(1), 32);
    assert_eq!(bcrypt_pbkdf_scratch_len(32), 32);
    assert_eq!(bcrypt_pbkdf_scratch_len(33), 64);
    // The OpenSSH v1 container derives a 32-byte key plus a 16-byte IV.
    assert_eq!(bcrypt_pbkdf_scratch_len(48), 64);
    assert_eq!(
        bcrypt_pbkdf_scratch_len(BCRYPT_PBKDF_MAX_OUTPUT_LEN),
        BCRYPT_PBKDF_MAX_OUTPUT_LEN
    );
}

/// More rounds give a different key, so the cost parameter is really fed
/// into the derivation rather than ignored.
#[test]
fn the_round_count_changes_the_result() {
    let mut four = [0u8; 32];
    let mut eight = [0u8; 32];
    let mut scratch = [0u8; 32];
    bcrypt_pbkdf(&V0_PASSPHRASE, &V0_SALT, 4, &mut four, &mut scratch).expect("derives");
    bcrypt_pbkdf(&V0_PASSPHRASE, &V0_SALT, 8, &mut eight, &mut scratch).expect("derives");
    assert_ne!(four, eight);
}

const SECRET: [u8; 32] = [0x42; 32];

fn rounds(n: u32) -> NonZeroU32 {
    NonZeroU32::new(n).expect("non-zero")
}

fn unhex(text: &str) -> PasswordHash {
    let mut out = [0u8; 32];
    for (i, slot) in out.iter_mut().enumerate() {
        *slot = u8::from_str_radix(&text[2 * i..2 * i + 2], 16).expect("hex");
    }
    out
}

#[test]
fn pbkdf2_matches_the_published_sha256_vectors() {
    // The de-facto standard PBKDF2-HMAC-SHA256 vectors (the SHA-256
    // re-computation of the RFC 6070 inputs, as published in the
    // RustCrypto and OpenSSL test suites).
    assert_eq!(
        pbkdf2_sha256(b"password", b"salt", rounds(1)),
        unhex("120fb6cffcf8b32c43e7225256c4f837a86548c92ccc35480805987cb70be17b"),
    );
    assert_eq!(
        pbkdf2_sha256(b"password", b"salt", rounds(2)),
        unhex("ae4d0c95af6b46d32d0adff928f06dd02a303f8ef3c251dfd6e2d85a95474c43"),
    );
    assert_eq!(
        pbkdf2_sha256(b"password", b"salt", rounds(4096)),
        unhex("c5e478d59288c841aa530db6845c4c8d962893a001ce4e11a4963873aa98134a"),
    );
}

#[test]
fn pbkdf2_inputs_are_all_load_bearing() {
    let base = pbkdf2_sha256(b"password", b"salt", rounds(2));
    assert_ne!(pbkdf2_sha256(b"passwore", b"salt", rounds(2)), base);
    assert_ne!(pbkdf2_sha256(b"password", b"selt", rounds(2)), base);
    assert_ne!(pbkdf2_sha256(b"password", b"salt", rounds(3)), base);
}

#[test]
fn pbkdf2_verify_accepts_genuine_and_rejects_tampered_hashes() {
    let hash = pbkdf2_sha256(b"correct horse", b"battery staple", rounds(16));
    assert!(pbkdf2_sha256_verify(
        b"correct horse",
        b"battery staple",
        rounds(16),
        &hash
    ));
    assert!(!pbkdf2_sha256_verify(
        b"wrong horse",
        b"battery staple",
        rounds(16),
        &hash
    ));
    let mut bad = hash;
    bad[0] ^= 0x01;
    assert!(!pbkdf2_sha256_verify(
        b"correct horse",
        b"battery staple",
        rounds(16),
        &bad
    ));
}

#[test]
fn derivation_is_deterministic_and_full_width() {
    let a = derive_key(&SECRET, b"arxfs/content");
    let b = derive_key(&SECRET, b"arxfs/content");
    assert_eq!(a, b);
    assert_eq!(a.len(), DERIVED_KEY_LEN);
}

#[test]
fn distinct_contexts_yield_independent_keys() {
    let content = derive_key(&SECRET, b"arxfs/content");
    let filename = derive_key(&SECRET, b"arxfs/filename");
    let meta = derive_key(&SECRET, b"arxfs/meta-mac");
    assert_ne!(content, filename);
    assert_ne!(content, meta);
    assert_ne!(filename, meta);
}

#[test]
fn distinct_secrets_yield_independent_keys() {
    let other = [0x43; 32];
    assert_ne!(
        derive_key(&SECRET, b"arxfs/content"),
        derive_key(&other, b"arxfs/content")
    );
}
